float pow2(float x) { return x*x; }

float perim(vec2 p1, vec2 p2, vec2 p3) {
    return length(p1-p2) + length(p2-p3) + length(p3-p1);
}

vec3 pos(int i, int n) {
    i = clamp(i, 1, n);
    vec4 r = texelFetch(iChannel0, ivec2(i,0), 0);
    r.z = float(i)/float(n) * iResolution.y;
    return r.xyz;
}

float sdLine(vec2 p, vec2 a, vec2 b) {
    p -= a, b -= a;
    float t = dot(p,b)/dot(b,b);
    t = clamp(t, 0., 1.);
    return length(p-b*t);
}

vec3 bezier3(float s, vec3 p1, vec3 p2, vec3 p3) {
    return mix(mix(p1,p2,s),mix(p2,p3,s),s);
}

// returns (f(s), f'(s), f''(s))
vec3 sinc(float x) {
    if (abs(x) <= 0.001)
        return vec3(1. - x*x/6., -x/3., -1./3. + x*x/10.);
    float f = sin(x)/x;
    float g = (cos(x) - f)/x;
    float h = -f - 2.*g/x;
    return vec3(f,g,h);
}

// returns (f(x), f'(x), f''(x))
vec3 lanczos(float x, float a) {
    vec3 u = sinc(PI*x)*vec3(1, PI, pow2(PI));
    vec3 v = sinc(PI*x/a)*vec3(1, PI/a, pow2(PI/a));
    float w1 = u.y*v.x + u.x*v.y;
    float w2 = u.z*v.x + 2.*u.y*v.y + u.x*v.z;
    return vec3(u.x*v.x, w1, w2); 
}

// returns (f(s), f'(s), f''(s))
mat3x4 bezier4(float s) {
    float t = 1. - s;
    vec4 w0 = vec4(t*t*t, t*t*s, t*s*s, s*s*s)*vec4(1,3,3,1);
    vec4 w1 = vec4(t*t, t*(2.*s - t), -s*(2.*t - s), -s*s)*3.;
    vec4 w2 = vec4(t, s - 2.*t, t - 2.*s, s)*6.;
    return mat3x4(w0,w1,w2);
}

// returns (f(s), f'(s), f''(s))
mat3x4 bspline4(float t) {
    float s = 1. - t;
    vec4 w0 = vec4(s*s*s, 3.*t*t*(t - 2.) + 4., 3.*s*s*(s - 2.) + 4., t*t*t)/6.;
    vec4 w1 = vec4(-s*s, 3.*t*t - 4.*t, -3.*s*s + 4.*s, t*t)/2.;
    vec4 w2 = vec4(s, 3.*t - 2., 3.*s - 2., t);
    return mat3x4(w0,w1,w2);
}

// i must be in the a..n-a+1 range.
// returns (f(i), f'(i), f''(i))
mat3x3 curve(float i, int n) {
    float s = fract(i);

    // control points
    vec3 p0 = pos(int(i-s)-1, n);
    vec3 p1 = pos(int(i-s)-0, n);
    vec3 p2 = pos(int(i-s)+1, n);
    vec3 p3 = pos(int(i-s)+2, n);

    // smooth f''(s) at connections
    mat3x4 w = bspline4(s);
    mat4x3 pts = mat4x3(p0,p1,p2,p3);

    return pts*w;
}

float glow(float d) {
    return pow(R0/abs(d), 1.5);
}

mat2x2 rot2(float phi) {
    float c = cos(phi), s = sin(phi);
    return mat2x2(c,s,-s,c);
}

vec2 project(vec3 p) {
    p.xz -= iResolution.x/2.;
    p.xz *= rot2(0.1*iTime*(iMouse.z > 0. ? 0. : 1.));
    p.xz += iResolution.x/2.;
    return p.xy;
}

vec3 color(vec2 p, int n) {
    if (n < 2) return vec3(0);
    float ds = max(1./BSEG, float(n)/NMAX);
    vec3 g;
    mat3x3 s0, s1, s2;
    vec3 p0, p1;

    for (float i = 0.0; i <= float(n); i += ds) {
        s0=s1, s1=s2, s2=curve(i, n);

        if (i < 1.0) continue;
        float d = sdLine(p, project(s1[0]), project(s2[0]));
        g += glow(d)*RGB;

        if (i < 2.0) continue;
        // https://en.wikipedia.org/wiki/Frenet%E2%80%93Serret_formulas
        vec3 t = s1[1];
        vec3 n = s1[2]/pow(1. + dot(t,t), 1.5);
        vec3 b = cross(t,n);
        mat3 tnb = mat3(normalize(t),normalize(n),normalize(b));

        vec2 rot = vec2(cos(iTime),sin(iTime));
        p0=p1, p1 = s1[0] + tnb*vec3(0,100.*rot);

        if (length(p0) > 0.) {
            g += glow(sdLine(p, project(p0), project(p1)))*RGB.gbr;
            g += 0.5*glow(sdLine(p, project(p1), project(s1[0])))*RGB.gbr;
        }
    }

    for (int i = 1; i <= n; i++)
        g += 5.0*RGB.grb*glow(length(p - project(pos(i,n))));

    return g;
}

void mainImage(out vec4 o, vec2 p) {
    vec4 conf = texelFetch(iChannel0, ivec2(0), 0);
    o = vec4(color(p, int(conf.x)), 1);
    if (p.y < 1.0 && p.x < conf.x)
        o.rgb = RGB*p.x/conf.x*2.;
}

const float INF = 1e10;
const float PI = radians(180.);
const float R0 = 3.;
const float NMAX = 500.;
const float BSEG = 15.;
const vec2 SHAPE = vec2(30, 3);
const vec3 RGB = 0.1*vec3(1.0,0.5,0.2);

// iChannel0[t,0].xy = iMouse.xy at frame t>0
// iChannel0[0,0].xy = (num_points, is_ended)

vec2 init(vec2 p, float n, float m) {
    if (p.x < 1.0)
        return vec2(n, 1);
    float a = 2.*PI*(p.x-1.5)/n;
    vec2 r = vec2(sin(a), cos(a))*(0.7+0.3*sin(a*m));
    return r*iResolution.y/2. + iResolution.xy/2.;
}

void mainImage(out vec4 o, in vec2 p) {
    if (p.y > 1.0)
        discard;
    if (iFrame == 0) {
        o.xy = init(p, SHAPE.x, SHAPE.y);
        return;
    }

    vec4 conf = texelFetch(iChannel0, ivec2(0), 0); // .x=len
    bool is_drawing = iMouse.z > 0.;
    bool is_ended = conf.y > 0.;

    if (p.x > 1.0) {
        o = texelFetch(iChannel0, ivec2(p), 0);
        if (is_drawing && int(p.x) == 1 + int(conf.x))
            o.xy = iMouse.xy;
    }

    if (max(p.x, p.y) < 1.) {
        o = conf;

        if (!is_drawing) {
            o.y = 1.;
            return;
        }

        if (iFrame%5 == 0)
            o.x += 1.;
        if (is_ended)
            o.x = o.y = 0.;
    }
}
